import React, { useState, useEffect } from "react";
import axios from "axios";
import { useNavigate, useLocation } from "react-router-dom";

const UserDetails = () => {
  const navigate = useNavigate();
  const location = useLocation();

  const {
    houseId,
    selectedDate,
    amount,
    days = 1,
    selectedDates = [],
  } = location.state ||
  JSON.parse(localStorage.getItem("bookingDetails") || "{}");
  const userId = localStorage.getItem("userId");

  const [formData, setFormData] = useState({
    name: "",
    phone: "",
    email: "",
    idProof: "",
    persons: 1,
  });
  const [otp, setOtp] = useState("");
  const [otpSent, setOtpSent] = useState(false);
  const [error, setError] = useState(null);
  const [isSending, setIsSending] = useState(false);
  const [isVerifying, setIsVerifying] = useState(false);

  const derivedSelectedDate =
    selectedDate ||
    (selectedDates.length > 0 ? [...selectedDates].sort()[0] : null);
  const derivedDays = days || selectedDates.length || 1;
  const derivedAmount = amount;

  useEffect(() => {
    const missingFields = [];
    if (!houseId) missingFields.push("houseId");
    if (!userId) missingFields.push("userId");
    if (!derivedSelectedDate) missingFields.push("selectedDate");
    if (!derivedAmount) missingFields.push("amount");

    console.log("Booking Details:", {
      houseId,
      userId,
      selectedDate: derivedSelectedDate,
      amount: derivedAmount,
      days: derivedDays,
      selectedDates,
      missingFields,
    });

    if (missingFields.length > 0) {
      setError(
        `Missing booking details: ${missingFields.join(
          ", "
        )}. Please try again.`
      );
      setTimeout(() => navigate("/homes"), 3000);
    } else if (!userId) {
      setError("Please log in to proceed with booking.");
      setTimeout(() => navigate("/login"), 3000);
    }

    if (location.state) {
      localStorage.setItem("bookingDetails", JSON.stringify(location.state));
    }
  }, [
    houseId,
    userId,
    derivedSelectedDate,
    derivedAmount,
    derivedDays,
    selectedDates,
    navigate,
    location.state,
  ]);

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSendOtp = async () => {
    if (isSending) return;
    if (!formData.phone || !formData.email) {
      setError("Phone and email are required.");
      return;
    }

    setIsSending(true);
    setError(null);

    const phone = formData.phone.startsWith("+91")
      ? formData.phone
      : `+91${formData.phone}`;

    try {
      const response = await axios.post("http://localhost:5000/api/send-otp", {
        phone,
        email: formData.email,
        userId,
      });
      console.log("Send OTP Response:", response.data);
      if (response.data.success) {
        setOtpSent(true);
        alert(
          `OTP sent to your mobile number (${phone}) and email (${formData.email}). Please check your SMS and inbox (including spam/junk folder). It is valid for 10 minutes.`
        );
      } else {
        setError(response.data.error || "Failed to send OTP.");
      }
    } catch (err) {
      console.error("Send OTP Error:", err.message, err.response?.data);
      setError(
        err.response?.data?.error || "Failed to send OTP. Please try again."
      );
    } finally {
      setIsSending(false);
    }
  };

  const handleVerifyOtp = async () => {
    if (isVerifying) return;
    if (!otp) {
      setError("Please enter the OTP.");
      return;
    }
    const missingFields = [];
    if (!houseId) missingFields.push("houseId");
    if (!userId) missingFields.push("userId");
    if (!derivedSelectedDate) missingFields.push("selectedDate");
    if (!derivedAmount) missingFields.push("amount");
    if (!/^\d{4}-\d{2}-\d{2}$/.test(derivedSelectedDate))
      setError("Selected date must be in YYYY-MM-DD format.");
    if (!Number.isInteger(derivedDays) || derivedDays <= 0)
      setError("Days must be a positive integer.");
    if (missingFields.length > 0) {
      setError(
        `Missing booking details: ${missingFields.join(
          ", "
        )}. Please try again.`
      );
      return;
    }

    setIsVerifying(true);
    setError(null);

    const phone = formData.phone.startsWith("+91")
      ? formData.phone
      : `+91${formData.phone}`;

    try {
      const response = await axios.post(
        "http://localhost:5000/api/verify-otp",
        {
          phone,
          otp,
          userId,
        }
      );
      console.log("Verify OTP Response:", response.data);
      if (response.data.success) {
        try {
          const bookingResponse = await axios.post(
            "http://localhost:5000/api/bookings",
            {
              houseId,
              userId,
              days: derivedDays,
              start_date: derivedSelectedDate,
              amount: derivedAmount,
              userDetails: formData,
            }
          );
          console.log("Booking Response:", bookingResponse.data);

          // Notify owner with all selected dates
          try {
            await axios.post("http://localhost:5000/api/owner/booking", {
              houseId,
              userId,
              userDetails: formData,
              selectedDates:
                selectedDates.length > 0
                  ? selectedDates
                  : [derivedSelectedDate],
            });
            console.log("Owner notification sent successfully");
          } catch (ownerNotifyErr) {
            console.error(
              "Owner Notification Error:",
              ownerNotifyErr.message,
              ownerNotifyErr.response?.data
            );
            // Don't block booking flow, just log the error
          }

          console.log(
            "Navigating to /booking-confirmation/",
            bookingResponse.data.bookingId
          );
          navigate(`/booking-confirmation/${bookingResponse.data.bookingId}`);
          localStorage.removeItem("bookingDetails");
        } catch (bookingErr) {
          console.error(
            "Booking Error:",
            bookingErr.message,
            bookingErr.response?.data
          );
          setError(
            bookingErr.response?.data?.error ||
              "Failed to create booking. Please try again."
          );
        }
      } else {
        setError(response.data.error || "Invalid OTP. Please try again.");
      }
    } catch (err) {
      console.error("Verify OTP Error:", err.message, err.response?.data);
      setError(
        err.response?.data?.error || "Failed to verify OTP. Please try again."
      );
    } finally {
      setIsVerifying(false);
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-gray-100 p-6">
      <div className="bg-white p-8 rounded-lg shadow-lg w-full max-w-md">
        <h2 className="text-2xl font-bold mb-6 text-center">User Details</h2>
        {!otpSent ? (
          <div className="space-y-4">
            <div>
              <label className="block text-gray-700">Name</label>
              <input
                type="text"
                name="name"
                value={formData.name}
                onChange={handleChange}
                className="w-full p-2 border rounded"
                required
                disabled={isSending}
              />
            </div>
            <div>
              <label className="block text-gray-700">Phone</label>
              <input
                type="text"
                name="phone"
                value={formData.phone}
                onChange={handleChange}
                className="w-full p-2 border rounded"
                placeholder="+91XXXXXXXXXX"
                required
                disabled={isSending}
              />
            </div>
            <div>
              <label className="block text-gray-700">Email</label>
              <input
                type="email"
                name="email"
                value={formData.email}
                onChange={handleChange}
                className="w-full p-2 border rounded"
                required
                disabled={isSending}
              />
            </div>
            <div>
              <label className="block text-gray-700">ID Proof</label>
              <input
                type="text"
                name="idProof"
                value={formData.idProof}
                onChange={handleChange}
                className="w-full p-2 border rounded"
                required
                disabled={isSending}
              />
            </div>
            <div>
              <label className="block text-gray-700">Number of Persons</label>
              <input
                type="number"
                name="persons"
                value={formData.persons}
                onChange={handleChange}
                className="w-full p-2 border rounded"
                min="1"
                required
                disabled={isSending}
              />
            </div>
            <button
              onClick={handleSendOtp}
              className="w-full bg-blue-500 text-white p-2 rounded hover:bg-blue-600 disabled:bg-gray-400"
              disabled={
                isSending ||
                !houseId ||
                !userId ||
                !derivedSelectedDate ||
                !derivedAmount
              }
            >
              {isSending ? "Sending OTP..." : "Send OTP"}
            </button>
          </div>
        ) : (
          <div className="space-y-4">
            <div>
              <label className="block text-gray-700">Enter OTP</label>
              <input
                type="text"
                value={otp}
                onChange={(e) => setOtp(e.target.value)}
                className="w-full p-2 border rounded"
                required
                disabled={isVerifying}
              />
            </div>
            <button
              onClick={handleVerifyOtp}
              className="w-full bg-blue-500 text-white p-2 rounded hover:bg-blue-600 disabled:bg-gray-400"
              disabled={
                isVerifying ||
                !houseId ||
                !userId ||
                !derivedSelectedDate ||
                !derivedAmount
              }
            >
              {isVerifying ? "Verifying OTP..." : "Verify OTP"}
            </button>
            <button
              onClick={handleSendOtp}
              className="w-full bg-gray-500 text-white p-2 rounded hover:bg-gray-600 disabled:bg-gray-400"
              disabled={isSending || isVerifying}
            >
              {isSending ? "Sending OTP..." : "Resend OTP"}
            </button>
          </div>
        )}
        {error && <div className="text-red-500 mt-4">{error}</div>}
      </div>
    </div>
  );
};

export default UserDetails;
